"use client";

import { forwardRef } from "react";
import { Button, type ButtonProps } from "../button/button";
import { shimmerButtonDefaults, type ShimmerButtonSpecProps } from "../generated/shimmer-button.types";
import { cx } from "../utils/cx";
import { motionVars } from "../utils/motion";

export interface ShimmerButtonProps extends ShimmerButtonSpecProps, Omit<ButtonProps, keyof ShimmerButtonSpecProps> {}

/** A button whose surface is crossed by a soft band of light, now and then. Builds on Button. */
export const ShimmerButton = forwardRef<HTMLButtonElement, ShimmerButtonProps>(function ShimmerButton(
  { children, duration = shimmerButtonDefaults.duration, isPaused = shimmerButtonDefaults.isPaused, className, style, ...rest },
  ref,
) {
  return (
    <Button
      {...rest}
      ref={ref}
      data-rdm-paused={isPaused || undefined}
      className={cx("relative overflow-hidden", className)}
      style={(values) => ({ ...motionVars({ "--rdm-d": `${duration}s` }), ...(typeof style === "function" ? style(values) : style) })}
    >
      <span className="relative z-[1] inline-flex items-center gap-2">{children}</span>
      <span aria-hidden="true" className="rdm-shimmer" />
    </Button>
  );
});

// Generated by rdloom codegen from specs/shimmer-button.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

import type { ReactNode } from "react";

export const shimmerButtonVariantValues = ["primary", "secondary", "ghost", "danger"] as const;
export const shimmerButtonSizeValues = ["sm", "md", "lg"] as const;

/** A button with a soft band of light that crosses its surface now and then, for one standout action. Builds on Button, so focus, disabled and loading work the same. */
export interface ShimmerButtonSpecProps {
  /**
   * Button label. Icon-only buttons must pass aria-label instead.
   */
  children: ReactNode;
  /**
   * Visual emphasis, as on Button.
   * @default "primary"
   */
  variant?: "primary" | "secondary" | "ghost" | "danger";
  /**
   * Height, padding and font size, as on Button.
   * @default "md"
   */
  size?: "sm" | "md" | "lg";
  /**
   * Seconds for one sweep, including the pause before the next.
   * @default 2.6
   */
  duration?: number;
  /**
   * Stops the animation. Moving content that lasts more than five seconds should be stoppable.
   * @default false
   */
  isPaused?: boolean;
  /**
   * Prevents interaction and dims the button.
   * @default false
   */
  isDisabled?: boolean;
  /**
   * Shows a spinner and blocks presses; the pending state is announced.
   * @default false
   */
  isLoading?: boolean;
  /**
   * Called when the button is pressed by mouse, touch or keyboard.
   */
  onPress?: () => void;
}

export const shimmerButtonDefaults = {
  variant: "primary",
  size: "md",
  duration: 2.6,
  isPaused: false,
  isDisabled: false,
  isLoading: false,
} as const;

export const shimmerButtonMeta = {
  "name": "ShimmerButton",
  "version": "0.1.0",
  "status": "experimental",
  "role": "button"
} as const;
